// Offline edge-provider lookups (#1807): an address matched against the published provider ranges, and
// against the DB-IP ASN Lite rows of edge-specific ASNs. Both tables are bundled files generated by
// scripts/refresh-edge-data.ts; nothing here makes a request.
import { isIP } from "node:net";

import asnData from "../../geoip-db/edge-asn.json";
import rangeData from "../../geoip-db/edge-ranges.json";
import snapshot from "../../geoip-db/SNAPSHOT.json";
import { parseV4, parseV6 } from "./ip";

export const EDGE_RANGES_FETCHED_AT: string = rangeData.fetchedAt;
export const EDGE_ASN_SNAPSHOT: string = snapshot.edge.asn.snapshot;
/** Provider ids the bundled data must cover (checked by a test). */
export const EDGE_RANGE_PROVIDERS = Object.keys(rangeData.providers);
export const EDGE_ASN_PROVIDERS = Object.keys(asnData.providers);

export interface EdgeRangeMatch {
  provider: string;
  name: string;
  /** True when the published list is the provider's whole cloud, not only its edge (Google Cloud). */
  broad: boolean;
}
export interface EdgeAsnMatch {
  provider: string;
  name: string;
  asn: number;
}

/** 128-bit value of an address; IPv4 (and ::ffff:a.b.c.d) is its own 32-bit space, tagged by `v6`. */
function toKey(ip: string): { v6: boolean; n: bigint } | null {
  const bare = ip.split("%")[0]!;
  const kind = isIP(bare);
  if (kind === 4) {
    const v = parseV4(bare);
    return v === null ? null : { v6: false, n: BigInt(v) };
  }
  if (kind !== 6) return null;
  const b = parseV6(bare);
  if (!b) return null;
  if (b.subarray(0, 10).every((x) => x === 0) && b[10] === 0xff && b[11] === 0xff) {
    return { v6: false, n: (BigInt(b[12]!) << 24n) | (BigInt(b[13]!) << 16n) | (BigInt(b[14]!) << 8n) | BigInt(b[15]!) };
  }
  let n = 0n;
  for (const x of b) n = (n << 8n) | BigInt(x);
  return { v6: true, n };
}

interface Cidr { v6: boolean; lo: bigint; hi: bigint }

function parseCidr(c: string): Cidr | null {
  const [addr, len] = c.split("/");
  const k = addr ? toKey(addr) : null;
  const bits = Number(len);
  if (!k || !Number.isInteger(bits)) return null;
  const width = k.v6 ? 128 : 32;
  if (bits < 0 || bits > width) return null;
  const host = (1n << BigInt(width - bits)) - 1n;
  const lo = k.n & ~host;
  return { v6: k.v6, lo, hi: lo | host };
}

let rangeIndex: Array<{ provider: string; name: string; broad: boolean; cidrs: Cidr[] }> | undefined;
function ranges() {
  return (rangeIndex ??= Object.entries(rangeData.providers).map(([provider, p]) => ({
    provider,
    name: p.name,
    broad: "broad" in p && p.broad === true,
    cidrs: p.cidrs.map(parseCidr).filter((c): c is Cidr => c !== null),
  })));
}

let asnIndex: Array<{ provider: string; name: string; ranges: Array<{ v6: boolean; lo: bigint; hi: bigint; asn: number }> }> | undefined;
function asns() {
  return (asnIndex ??= Object.entries(asnData.providers).map(([provider, p]) => ({
    provider,
    name: p.name,
    ranges: (p.ranges as Array<[string, string, number]>).flatMap(([s, e, asn]) => {
      const a = toKey(s);
      const b = toKey(e);
      return a && b && a.v6 === b.v6 ? [{ v6: a.v6, lo: a.n, hi: b.n, asn }] : [];
    }),
  })));
}

/** Providers whose published range list contains the address, narrowest (non-broad) first. */
export function matchEdgeRanges(ip: string): EdgeRangeMatch[] {
  const k = toKey(ip);
  if (!k) return [];
  return ranges()
    .filter((p) => p.cidrs.some((c) => c.v6 === k.v6 && k.n >= c.lo && k.n <= c.hi))
    .map((p) => ({ provider: p.provider, name: p.name, broad: p.broad }))
    .sort((a, b) => Number(a.broad) - Number(b.broad));
}

/** The edge provider whose edge-specific ASN rows contain the address, if any. */
export function matchEdgeAsn(ip: string): EdgeAsnMatch | null {
  const k = toKey(ip);
  if (!k) return null;
  for (const p of asns()) {
    const r = p.ranges.find((x) => x.v6 === k.v6 && k.n >= x.lo && k.n <= x.hi);
    if (r) return { provider: p.provider, name: p.name, asn: r.asn };
  }
  return null;
}
